#include <iostream>
#include <sstream>
#include <string>

int main() {
    // Simulate delimited file content using stringstream
    std::string data = "New York#New Mexico#Texas#Indiana";
    std::stringstream inputStream(data);
    std::stringstream outputStream;

    // 1. Reading fields with custom delimiter '#'
    std::string city;
    while (std::getline(inputStream, city, '#')) {
        std::cout << city << "\n";
    }

    // 2. Safe character-by-character copy without eof() extra-byte bug
    std::stringstream sourceStream("AlphaBeta");
    char ch;
    while (sourceStream.get(ch)) {
        outputStream.put(ch);
    }

    std::cout << "Copied: " << outputStream.str() << "\n";
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

int main() {
    // Simulate fstream multi-mode behavior using stringstream
    // 1. Initial write (simulating ios::out)
    std::stringstream stream;
    stream << "Dallas Houston Atlanta";

    // 2. Append operation (simulating ios::out | ios::app)
    stream.seekp(0, std::ios::end);
    stream << " Savannah Austin Chicago";

    // 3. Read back all contents (simulating ios::in)
    stream.seekg(0, std::ios::beg);
    std::string city;
    while (stream >> city) {
        std::cout << city << " ";
    }
    std::cout << "\nDone\n";
    return 0;
}
